var s = s_facts;

var t = t_facts;

var s_by_1 = index(s, [0]);
var instances_h0 = [].concat(
  // h0 :- r(X), s(X,Y), t(Y).
  (function() {
    return _.flatten(map(function(e1) {
      var X = e1.t[0];
      return _.flatten(map(function(e2) {
        var Y = e2.t[1];
        return _.flatten(map(function(e3) {
          return [['h0', [], and([e1.v, e2.v, e3.v])]];
