  // h1 :- r(X), s(X,Y).
  (function() {
    return _.flatten(map(function(e1) {
      var X = e1.t[0];
      return _.flatten(map(function(e2) {
        var Y = e2.t[1];
        return [['h1', [], and([e1.v, e2.v])]];
      }, (s_by_1[keyOf([X])] || [])));
    }, _.values(r)));
  })(),
  // h1 :- s(X,Y), t(Y).
  (function() {
    return _.flatten(map(function(e1) {
      var X = e1.t[0];
      var Y = e1.t[1];
      return _.flatten(map(function(e2) {
        return [['h1', [], and([e1.v, e2.v])]];
      }, probe(t, [Y])));
    }, _.values(s)));
  })()
);
var h1 = relation({}, instances_h1);

var instances_safe = [].concat(
  // safe :- r(X), s(X,Y).
  (function() {
    return _.flatten(map(function(e1) {
      var X = e1.t[0];
      return _.flatten(map(function(e2) {
        var Y = e2.t[1];
        return [['safe', [], and([e1.v, e2.v])]];
      }, (s_by_1[keyOf([X])] || [])));
    }, _.values(r)));
  })()
);
var safe = relation({}, instances_safe);

