texts.eb386286853c6c78d735d9458d27508955138e16:
// pdb10.pl: a ProbLog program written in Psi by tddlog's scripts/problog2ppl.py,
// first order as it is written. A relation is a column of integers for each
// argument and a column of Booleans for whether each tuple holds, a symbol a
// number of its own; each probabilistic fact is a coin of its own (`flip`), the
// facts arrays in the program; each rule is a loop over the relations its body
// joins, a tuple looked up by a scan. The value is the array of the queries'
// holdings, given the evidence (`observe`): one is asked a run, its `return`
// made `return queries[K];`.
//
//   psi --dp PROGRAM.psi
def main() {
  // the symbols as numbers: c0 1000000, c1 1000001, c2 1000002, c3 1000003, c4 1000004, c5 1000005, c6 1000006, c7 1000007, c8 1000008, c9 1000009
  // r/1: 10 facts
  r_facts_1 := [1000000, 1000001, 1000002, 1000003, 1000004, 1000005, 1000006, 1000007, 1000008, 1000009]: ℤ[];
  r_facts_p := [0.17, 0.74, 0.5, 0.64, 0.13, 0.8, 0.74, 0.45, 0.26, 0.86]: ℝ[];
  r_facts_h := array(r_facts_p.length, false);
  for i in [0..r_facts_p.length) { if r_facts_p[i] < 1 { r_facts_h[i] = flip(r_facts_p[i]); } else { r_facts_h[i] = true; } }
  // t/1: 10 facts
  t_facts_1 := [1000000, 1000001, 1000002, 1000003, 1000004, 1000005, 1000006, 1000007, 1000008, 1000009]: ℤ[];
  t_facts_p := [0.81, 0.28, 0.45, 0.76, 0.08, 0.44, 0.05, 0.7, 0.9, 0.08]: ℝ[];
  t_facts_h := array(t_facts_p.length, false);
  for i in [0..t_facts_p.length) { if t_facts_p[i] < 1 { t_facts_h[i] = flip(t_facts_p[i]); } else { t_facts_h[i] = true; } }
  // s/2: 20 facts
  s_facts_1 := [1000000, 1000000, 1000001, 1000001, 1000002, 1000002, 1000003, 1000003, 1000004, 1000004, 1000005, 1000005, 1000006, 1000006, 1000007, 1000007, 1000008, 1000008, 1000009, 1000009]: ℤ[];
  s_facts_2 := [1000000, 1000008, 1000003, 1000006, 1000007, 1000009, 1000003, 1000007, 1000006, 1000008, 1000001, 1000004, 1000006, 1000008, 1000003, 1000004, 1000007, 1000008, 1000003, 1000007]: ℤ[];
  s_facts_p := [0.0117, 0.1686, 0.1407, 0.105, 0.1095, 0.0722, 0.1814, 0.1768, 0.176, 0.028, 0.1438, 0.1712, 0.1014, 0.1738, 0.0611, 0.1852, 0.0808, 0.1636, 0.1439, 0.0828]: ℝ[];
  s_facts_h := array(s_facts_p.length, false);
  for i in [0..s_facts_p.length) { if s_facts_p[i] < 1 { s_facts_h[i] = flip(s_facts_p[i]); } else { s_facts_h[i] = true; } }

  r_1 := r_facts_1;
  r_h := r_facts_h;

  s_1 := s_facts_1;
  s_2 := s_facts_2;
  s_h := s_facts_h;

  t_1 := t_facts_1;
  t_h := t_facts_h;

  h0_h := []: 𝔹[];
  // h0 :- r(X), s(X,Y), t(Y).
  for k1 in [0..r_h.length) {
    X := r_1[k1];
    x2 := r_h[k1];
    for k3 in [0..s_h.length) {
      if s_1[k3] == X {
        Y := s_2[k3];
        x4 := s_h[k3];
        for k5 in [0..t_h.length) {
          if t_1[k5] == Y {
            x6 := t_h[k5];
            v7 := x2 && x4 && x6;
            f8 := false;
            for k9 in [0..h0_h.length) {
              if true { h0_h[k9] = h0_h[k9] || v7; f8 = true; }
            }
            if !f8 { h0_h = h0_h ~ [v7]; }
          }
        }
      }
    }
  }

  h1_h := []: 𝔹[];
  // h1 :- r(X), s(X,Y).
  for k10 in [0..r_h.length) {
    X := r_1[k10];
    x11 := r_h[k10];
    for k12 in [0..s_h.length) {
      if s_1[k12] == X {
        Y := s_2[k12];
        x13 := s_h[k12];
        v14 := x11 && x13;
        f15 := false;
        for k16 in [0..h1_h.length) {
          if true { h1_h[k16] = h1_h[k16] || v14; f15 = true; }
        }
        if !f15 { h1_h = h1_h ~ [v14]; }
      }
    }
  }
  // h1 :- s(X,Y), t(Y).
  for k17 in [0..s_h.length) {
    X := s_1[k17];
    Y := s_2[k17];
    x18 := s_h[k17];
    for k19 in [0..t_h.length) {
      if t_1[k19] == Y {
        x20 := t_h[k19];
        v21 := x18 && x20;
        f22 := false;
        for k23 in [0..h1_h.length) {
          if true { h1_h[k23] = h1_h[k23] || v21; f22 = true; }
        }
        if !f22 { h1_h = h1_h ~ [v21]; }
      }
    }
  }

  safe_h := []: 𝔹[];
  // safe :- r(X), s(X,Y).
  for k24 in [0..r_h.length) {
    X := r_1[k24];
    x25 := r_h[k24];
    for k26 in [0..s_h.length) {
      if s_1[k26] == X {
        Y := s_2[k26];
        x27 := s_h[k26];
        v28 := x25 && x27;
        f29 := false;
        for k30 in [0..safe_h.length) {
          if true { safe_h[k30] = safe_h[k30] || v28; f29 = true; }
        }
        if !f29 { safe_h = safe_h ~ [v28]; }
      }
    }
  }

  q31 := false;
  for q31_k in [0..h0_h.length) { if true { q31 = h0_h[q31_k]; } }
  q32 := false;
  for q32_k in [0..h1_h.length) { if true { q32 = h1_h[q32_k]; } }
  q33 := false;
  for q33_k in [0..safe_h.length) { if true { q33 = safe_h[q33_k]; } }
  queries := [q31, q32, q33];
  return queries[2];
}

